<template>
  <section class="cost-page">
    <header class="cost-hero"><div><span>FINOPS CONTROL PLANE</span><h1>成本与配额治理</h1><p>统一计量 LLM、Tool/MCP、Sandbox 与 Delegation，执行前预算熔断，执行后审计告警。</p></div><el-button color="#f4bb52" :loading="loading" @click="loadAll">刷新账本</el-button></header>
    <div class="metric-grid" v-if="dashboard">
      <article><label>本月费用</label><strong>{{ money(dashboard.projectUsage.amount) }}</strong></article>
      <article><label>LLM Token</label><strong>{{ number(dashboard.projectUsage.llmTokens) }}</strong></article>
      <article><label>Tool / MCP</label><strong>{{ number(dashboard.projectUsage.toolCalls) }}</strong></article>
      <article><label>Sandbox 秒</label><strong>{{ number(dashboard.projectUsage.sandboxSeconds) }}</strong></article>
      <article :class="{danger:dashboard.projectUsage.unpricedEvents>0}"><label>未定价事件</label><strong>{{ dashboard.projectUsage.unpricedEvents }}</strong></article>
    </div>
    <el-tabs v-model="activeTab" class="panel">
      <el-tab-pane label="预算看板" name="dashboard">
        <el-empty v-if="!dashboard?.policies.length" description="当前作用域暂无预算策略" />
        <div class="policy-cards"><article v-for="item in dashboard?.policies" :key="item.policy.id"><div class="policy-title"><strong>{{ item.policy.policyName }}</strong><el-tag :type="item.policy.hardLimit?'danger':'warning'">{{ item.policy.hardLimit?'硬熔断':'仅告警' }}</el-tag></div><p>{{ item.policy.scopeType }} #{{ item.policy.scopeId }} · {{ item.policy.periodType }}</p><div v-for="metric in item.metrics" :key="metric.metric" class="progress"><span>{{ metricLabel(metric.metric) }} {{ number(metric.current) }} / {{ number(metric.limit) }}</span><el-progress :percentage="Math.min(metric.usagePercent,100)" :status="metric.usagePercent>=100?'exception':metric.usagePercent>=item.policy.warningPercent?'warning':''" /></div></article></div>
      </el-tab-pane>
      <el-tab-pane label="用量流水" name="usage">
        <div class="toolbar"><el-select v-model="usageType" clearable placeholder="全部资源"><el-option v-for="type in resourceTypes" :key="type" :value="type" :label="type.toUpperCase()" /></el-select><el-button type="primary" @click="loadUsage">查询</el-button></div>
        <el-table :data="usage" border stripe><el-table-column prop="occurredAt" label="时间" min-width="170" :formatter="formatTableDateTime"/><el-table-column prop="eventCode" label="事件" min-width="220"/><el-table-column prop="resourceType" label="类型" width="100"/><el-table-column prop="resourceCode" label="资源" min-width="170"/><el-table-column label="用量" min-width="140"><template #default="{row}">{{ row.resourceType==='llm'?`${row.inputUnits}+${row.outputUnits} token`:`${row.quantity} ${row.unit}` }}</template></el-table-column><el-table-column label="费用" width="120"><template #default="{row}">{{ money(row.amount,row.currency) }}</template></el-table-column><el-table-column label="计价" width="100"><template #default="{row}"><el-tag :type="row.pricingStatus==='priced'?'success':'warning'">{{ row.pricingStatus }}</el-tag></template></el-table-column><el-table-column prop="executionStatus" label="执行" width="100"/></el-table>
      </el-tab-pane>
      <el-tab-pane label="资源价格" name="prices">
        <div class="toolbar"><el-button type="primary" @click="openPrice()">新增价格</el-button></div>
        <el-table :data="prices" border><el-table-column prop="resourceType" label="类型" width="110"/><el-table-column prop="resourceCode" label="资源编码" min-width="180"/><el-table-column prop="inputPricePer1000" label="输入/千单位"/><el-table-column prop="outputPricePer1000" label="输出/千单位"/><el-table-column prop="unitPrice" label="单次/单秒"/><el-table-column prop="currency" label="币种" width="80"/><el-table-column prop="status" label="状态" width="90"/><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" @click="openPrice(row)">编辑</el-button></template></el-table-column></el-table>
      </el-tab-pane>
      <el-tab-pane label="预算策略" name="budgets">
        <div class="toolbar"><el-button type="primary" @click="openBudget()">新增策略</el-button></div>
        <el-table :data="budgets" border><el-table-column prop="policyCode" label="编码" min-width="160"/><el-table-column prop="policyName" label="名称" min-width="170"/><el-table-column label="作用域" min-width="130"><template #default="{row}">{{ row.scopeType }} #{{ row.scopeId }}</template></el-table-column><el-table-column prop="periodType" label="周期" width="90"/><el-table-column label="限制" min-width="280"><template #default="{row}">{{ limits(row) }}</template></el-table-column><el-table-column label="模式" width="100"><template #default="{row}"><el-tag :type="row.hardLimit?'danger':'warning'">{{ row.hardLimit?'硬熔断':'仅告警' }}</el-tag></template></el-table-column><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" @click="openBudget(row)">编辑</el-button></template></el-table-column></el-table>
      </el-tab-pane>
      <el-tab-pane label="预算告警" name="alerts"><el-table :data="alerts" border><el-table-column prop="triggeredAt" label="时间" min-width="170" :formatter="formatTableDateTime"/><el-table-column prop="policyName" label="策略" min-width="150"/><el-table-column prop="message" label="命中解释" min-width="320"/><el-table-column prop="status" label="状态" width="110"/><el-table-column label="操作" width="170"><template #default="{row}"><el-button v-if="row.status==='open'" link @click="setAlert(row.id,'acknowledged')">确认</el-button><el-button v-if="row.status!=='resolved'" link type="success" @click="setAlert(row.id,'resolved')">关闭</el-button></template></el-table-column></el-table></el-tab-pane>
    </el-tabs>
    <el-dialog v-model="priceVisible" :title="priceForm.id?'编辑资源价格':'新增资源价格'" width="650"><el-form label-width="140"><el-form-item label="资源类型"><el-select v-model="priceForm.resourceType"><el-option v-for="type in resourceTypes" :key="type" :value="type" /></el-select></el-form-item><el-form-item label="资源编码"><el-input v-model="priceForm.resourceCode"/></el-form-item><el-form-item label="输入/千单位"><el-input-number v-model="priceForm.inputPricePer1000" :min="0" :precision="6"/></el-form-item><el-form-item label="输出/千单位"><el-input-number v-model="priceForm.outputPricePer1000" :min="0" :precision="6"/></el-form-item><el-form-item label="单次/单秒"><el-input-number v-model="priceForm.unitPrice" :min="0" :precision="6"/></el-form-item><el-form-item label="币种/状态"><el-input v-model="priceForm.currency" style="width:120px"/><el-select v-model="priceForm.status" style="margin-left:12px;width:130px"><el-option value="enabled"/><el-option value="disabled"/></el-select></el-form-item></el-form><template #footer><el-button @click="priceVisible=false">取消</el-button><el-button type="primary" @click="savePrice">保存</el-button></template></el-dialog>
    <el-dialog v-model="budgetVisible" :title="budgetForm.id?'编辑预算策略':'新增预算策略'" width="760"><el-form label-width="150"><el-form-item label="编码 / 名称"><el-input v-model="budgetForm.policyCode" style="width:45%"/><el-input v-model="budgetForm.policyName" style="width:52%;margin-left:3%"/></el-form-item><el-form-item label="作用域"><el-select v-model="budgetForm.scopeType"><el-option v-for="v in ['tenant','project','agent','user']" :key="v" :value="v"/></el-select><el-input-number v-model="budgetForm.scopeId" :min="1" style="margin-left:12px"/></el-form-item><el-form-item label="周期 / 预警"><el-select v-model="budgetForm.periodType"><el-option value="daily"/><el-option value="monthly"/></el-select><el-input-number v-model="budgetForm.warningPercent" :min="1" :max="100" style="margin-left:12px"/>%</el-form-item><div class="form-grid"><el-form-item label="费用上限"><el-input-number v-model="budgetForm.budgetAmount" :min="0"/></el-form-item><el-form-item label="LLM Token"><el-input-number v-model="budgetForm.llmTokenLimit" :min="0"/></el-form-item><el-form-item label="Tool 次数"><el-input-number v-model="budgetForm.toolCallLimit" :min="0"/></el-form-item><el-form-item label="Sandbox 秒"><el-input-number v-model="budgetForm.sandboxSecondLimit" :min="0"/></el-form-item><el-form-item label="Delegation 次数"><el-input-number v-model="budgetForm.delegationCallLimit" :min="0"/></el-form-item><el-form-item label="优先级"><el-input-number v-model="budgetForm.priority" :min="1"/></el-form-item></div><el-form-item label="策略行为"><el-switch v-model="budgetForm.hardLimit" active-text="超限硬熔断" inactive-text="只告警"/><el-select v-model="budgetForm.status" style="margin-left:20px"><el-option value="enabled"/><el-option value="disabled"/></el-select></el-form-item></el-form><template #footer><el-button @click="budgetVisible=false">取消</el-button><el-button type="primary" @click="saveBudget">保存</el-button></template></el-dialog>
  </section>
</template>
<script setup lang="ts">
import { onMounted, reactive, ref } from "vue";import { ElMessage } from "element-plus";import { formatTableDateTime } from "@/utils/dateTime";import { createBudget,createPrice,fetchBudgetAlerts,fetchBudgets,fetchCostDashboard,fetchPrices,fetchUsage,updateBudget,updateBudgetAlert,updatePrice } from "@/api/costGovernance";import type { BudgetPolicy,CostDashboard,ResourcePrice,UsageEvent,BudgetAlert } from "@/types/costGovernance";
const resourceTypes=["llm","tool","mcp","sandbox","delegation"];const activeTab=ref("dashboard"),loading=ref(false),usageType=ref("");const dashboard=ref<CostDashboard|null>(null),usage=ref<UsageEvent[]>([]),prices=ref<ResourcePrice[]>([]),budgets=ref<BudgetPolicy[]>([]),alerts=ref<BudgetAlert[]>([]);const priceVisible=ref(false),budgetVisible=ref(false);
const priceForm=reactive<any>({});const budgetForm=reactive<any>({});
function defaultPrice(){return{id:null,resourceType:"llm",resourceCode:"",inputPricePer1000:0,outputPricePer1000:0,unitPrice:0,currency:"CNY",status:"enabled",effectiveFrom:new Date().toISOString().slice(0,19),effectiveTo:null}}
function defaultBudget(){return{id:null,policyCode:"",policyName:"",scopeType:"project",scopeId:1,periodType:"monthly",budgetAmount:null,llmTokenLimit:null,toolCallLimit:null,sandboxSecondLimit:null,delegationCallLimit:null,warningPercent:80,hardLimit:true,currency:"CNY",priority:100,status:"enabled",effectiveFrom:new Date().toISOString().slice(0,19),effectiveTo:null}}
async function loadAll(){loading.value=true;try{[dashboard.value,prices.value,budgets.value,alerts.value]=await Promise.all([fetchCostDashboard(),fetchPrices(),fetchBudgets(),fetchBudgetAlerts()]);await loadUsage()}catch(e){ElMessage.error(error(e))}finally{loading.value=false}}
async function loadUsage(){usage.value=await fetchUsage({resourceType:usageType.value||undefined,limit:500})}function openPrice(row?:ResourcePrice){Object.assign(priceForm,row?{...row}:defaultPrice());priceVisible.value=true}function openBudget(row?:BudgetPolicy){Object.assign(budgetForm,row?{...row}:defaultBudget());budgetVisible.value=true}
async function savePrice(){try{const{id,...payload}=priceForm;id?await updatePrice(id,payload):await createPrice(payload);priceVisible.value=false;ElMessage.success("资源价格已保存");await loadAll()}catch(e){ElMessage.error(error(e))}}
async function saveBudget(){try{const{id,...payload}=budgetForm;id?await updateBudget(id,payload):await createBudget(payload);budgetVisible.value=false;ElMessage.success("预算策略已保存");await loadAll()}catch(e){ElMessage.error(error(e))}}
async function setAlert(id:number,status:string){await updateBudgetAlert(id,status);alerts.value=await fetchBudgetAlerts();ElMessage.success("告警状态已更新")}
function money(v:number,c="CNY"){return`${c} ${Number(v||0).toFixed(4)}`}function number(v:number){return Number(v||0).toLocaleString()}function metricLabel(v:string){return({amount:"费用",llm_tokens:"LLM Token",tool_calls:"Tool 调用",sandbox_seconds:"Sandbox 秒",delegation_calls:"Delegation"} as Record<string,string>)[v]||v}function limits(v:BudgetPolicy){return[[v.budgetAmount,"费用"],[v.llmTokenLimit,"Token"],[v.toolCallLimit,"Tool"],[v.sandboxSecondLimit,"Sandbox秒"],[v.delegationCallLimit,"委派"]].filter(x=>x[0]!=null).map(x=>`${x[1]}=${x[0]}`).join(" · ")}function error(e:unknown){return e instanceof Error?e.message:"操作失败"}onMounted(loadAll);
</script>
<style scoped>.cost-page{min-width:0}.cost-hero{display:flex;justify-content:space-between;align-items:end;padding:30px;color:#fff8e8;background:radial-gradient(circle at 80% 10%,#62532b,transparent 30%),linear-gradient(125deg,#111d22,#173842);border-radius:20px 20px 0 0}.cost-hero span{font:600 11px Georgia;letter-spacing:.2em;color:#f4bb52}.cost-hero h1{margin:8px 0;font:700 34px Georgia}.cost-hero p{margin:0;color:#bed0cf}.metric-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;padding:18px;background:#e9efed}.metric-grid article{padding:18px;background:#fff;border-left:4px solid #2b796e}.metric-grid label{display:block;color:#647b78}.metric-grid strong{display:block;margin-top:7px;font:700 24px Georgia;color:#173842}.metric-grid .danger{border-color:#c64d3f}.panel{padding:18px 20px 25px;background:#fff;border-radius:0 0 20px 20px}.policy-cards{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.policy-cards article{padding:18px;border:1px solid #d9e3df;border-radius:12px}.policy-title,.toolbar{display:flex;justify-content:space-between;gap:10px}.progress{margin-top:13px}.progress span{font-size:13px;color:#536966}.toolbar{justify-content:flex-start;margin-bottom:14px}.form-grid{display:grid;grid-template-columns:1fr 1fr}@media(max-width:1000px){.metric-grid{grid-template-columns:repeat(2,1fr)}.policy-cards,.form-grid{grid-template-columns:1fr}}</style>
